Workflow data transformation module for processing step outputs.

This module provides a transformation function that safely evaluates
a user-provided Python expression string to map input data to an output
dictionary. Only dictionary literals, variable references to `input_data`,
arithmetic, comparison, and logical operators are permitted.
"""

import ast
from typing import Any, Dict


class _UnsafeExpression(Exception):
    """Raised when an expression contains disallowed constructs."""
    pass


class _SafeExpressionValidator(ast.NodeVisitor):
    """
    AST visitor that validates only a safe subset of Python expressions.
    Allowed constructs:
        - literals (numbers, strings, booleans, None, lists, tuples, sets, dicts)
        - the variable `input_data`
        - subscripting (including slices)
        - arithmetic, comparison, and logical operators
        - unary operators
    Disallowed constructs:
        - function/method/constructor calls
        - attribute access (except implicit ones like `__class__`)
        - imports, exec, eval, and all other statements
    """

