    _LITERAL_NODES = (
        ast.List, ast.Tuple, ast.Set, ast.Dict,
        ast.Num, ast.Str, ast.Bytes, ast.NameConstant,
    )
    if hasattr(ast, "Constant"):
        _LITERAL_NODES += (ast.Constant,)

    def visit_Expression(self, node: ast.Expression) -> None:
        """Handle top-level Expression node (mode='eval')."""
        self.visit(node.body)

    def visit_Name(self, node: ast.Name) -> None:
        """Allow only the variable 'input_data'."""
        if node.id != "input_data":
            raise _UnsafeExpression(f"Disallowed variable name: {node.id}")
        # Check that the context is Load (reading the variable).
        if not isinstance(node.ctx, ast.Load):
            raise _UnsafeExpression("Variable context must be Load.")

    def visit_Subscript(self, node: ast.Subscript) -> None:
        """Allow subscripting (e.g., input_data['key'])."""
        self.visit(node.value)
        # In Python < 3.9, the slice is wrapped in an Index node.
        if isinstance(node.slice, ast.Index):
            # Deprecated but still present in some versions.
            self.visit(node.slice.value)  # type: ignore[attr-defined]
        else:
            self.visit(node.slice)

    def visit_Index(self, node: ast.Index) -> None:
        """Forward legacy Index to its value."""
        self.visit(node.value)  # type: ignore[attr-defined]

    def visit_Slice(self, node: ast.Slice) -> None:
        """Allow slices (e.g., input_data[1:2])."""
        if node.lower is not None:
            self.visit(node.lower)
        if node.upper is not None:
            self.visit(node.upper)
        if node.step is not None:
            self.visit(node.step)

    def visit_ExtSlice(self, node: ast.ExtSlice) -> None:
        """Allow extended slices (deprecated but handle for safety)."""
        for dim in node.dims:
            self.visit(dim)

    def visit_BinOp(self, node: ast.BinOp) -> None:
        """Allow binary operations like +, -, *, /, etc."""
        self.visit(node.left)
        self.visit(node.right)

    def visit_UnaryOp(self, node: ast.UnaryOp) -> None:
        """Allow unary operations like -x, +x, not x."""
        self.visit(node.operand)

    def visit_BoolOp(self, node: ast.BoolOp) -> None:
        """Allow boolean operations (and, or)."""
        for value in node.values:
            self.visit(value)

    def visit_Compare(self, node: ast.Compare) -> None:
        """Allow comparisons (<, >, ==, etc.)."""
        self.visit(node.left)
        for comparator in node.comparators:
            self.visit(comparator)

    def visit_IfExp(self, node: ast.IfExp) -> None:
        """Allow conditional expressions (x if cond else y)."""
        self.visit(node.test)
        self.visit(node.body)
        self.visit(node.orelse)

    def generic_visit(self, node: ast.AST) -> None:
        """All other nodes are disallowed and will raise an error."""
        raise _UnsafeExpression(f"Disallowed construct: {type(node).__name__}")

    # Stub out nodes that we never need to visit deeper.
    def visit_Expr(self, node: ast.Expr) -> None:
        """Top-level expression wrapper (statement)."""
        self.visit(node.value)

    # Allow all literal nodes without further checks.
    def visit_Constant(self, node: ast.Constant) -> None:
        pass

    def visit_Num(self, node: ast.Num) -> None:
        pass

    def visit_Str(self, node: ast.Str) -> None:
        pass

    def visit_Bytes(self, node: ast.Bytes) -> None:
        pass

    def visit_NameConstant(self, node: ast.NameConstant) -> None:
        pass

    def visit_List(self, node: ast.List) -> None:
        for elt in node.elts:
            self.visit(elt)

    def visit_Tuple(self, node: ast.Tuple) -> None:
        for elt in node.elts:
            self.visit(elt)

    def visit_Set(self, node: ast.Set) -> None:
        for elt in node.elts:
            self.visit(elt)

    def visit_Dict(self, node: ast.Dict) -> None:
        for key in node.keys:
            self.visit(key)
        for value in node.values:
            self.visit(value)


