    validator = _SafeExpressionValidator()
    try:
        validator.visit(tree)
    except _UnsafeExpression as e:
        raise ValueError(f"Unsafe expression: {e}")

    # Compile the validated AST.
    compiled_code = compile(tree, '<transform_map_expr>', 'eval')

    # Execute in a restricted environment.
    # `__builtins__` is set to None to prevent access to any built‑in functions.
    # The only variable available is `input_data`.
    restricted_globals = {"__builtins__": None}
    restricted_locals = {"input_data": input_data}

    result = eval(compiled_code, restricted_globals, restricted_locals)

    if not isinstance(result, dict):
        raise TypeError(
            f"The expression must evaluate to a dictionary, got {type(result).__name__}"
        )

    return result

