        left = _safe_eval(node.left, context)
        right = _safe_eval(node.right, context)
        op_type = type(node.op)
        if op_type in _ALLOWED_BINARY_OPS:
            return _ALLOWED_BINARY_OPS[op_type](left, right)
        raise ValueError(
            f"Binary operator '{op_type.__name__}' is not allowed"
        )

