        operand = _safe_eval(node.operand, context)
        op_type = type(node.op)
        if op_type in _ALLOWED_UNARY_OPS:
            return _ALLOWED_UNARY_OPS[op_type](operand)
        raise ValueError(
            f"Unary operator '{op_type.__name__}' is not allowed"
        )

