        # Short-circuit evaluation for `and` / `or`
        if isinstance(node.op, ast.And):
            result = _safe_eval(node.values[0], context)
            for v in node.values[1:]:
                if not result:
                    return result
                result = _safe_eval(v, context)
            return result
        if isinstance(node.op, ast.Or):
            for v in node.values:
                val = _safe_eval(v, context)
                if val:
                    return val
            return val
