            f"Boolean operator '{type(node.op).__name__}' is not allowed"
        )

    if isinstance(node, ast.Compare):
        left = _safe_eval(node.left, context)
        for op, comparator in zip(node.ops, node.comparators):
            right = _safe_eval(comparator, context)
            op_type = type(op)
            if op_type in _ALLOWED_COMP_OPS:
                result = _ALLOWED_COMP_OPS[op_type](left, right)
                if not result:
                    return False
                left = right
            else:
                raise ValueError(
                    f"Comparison operator '{op_type.__name__}' is not allowed"
                )
        return True

