    _validate_expression(tree, allowed_names)

    # Evaluate the expression in a restricted environment.
    eval_globals = {"__builtins__": safe_builtins}
    eval_locals = {"input_data": input_data}

    try:
        result = eval(transform_map_expr, eval_globals, eval_locals)
    except Exception as e:
        raise ValueError(f"Error evaluating transform expression: {e}")

    if not isinstance(result, dict):
        raise ValueError(
            f"Transform expression must evaluate to a dict, got {type(result).__name__}"
        )

    return result
